type AnalyticsEventName = 'page_view' | 'tool_success' | 'tool_error' | 'share_copy' | 'share_open' | 'beginner_section_view' | 'beginner_example_click' | 'result_explainer_view' | 'internal_nav' | 'tool_start' | 'owned_list_add' | 'owned_list_remove' | 'owned_list_clear' | 'owned_list_apply';
type SharePayload = Record<string, string | number | boolean | undefined>;
declare global {
  interface Window {
    palcalculatorEvents?: Array<{ event: AnalyticsEventName; payload: Record<string, unknown>; ts: string }>;
    palcalculatorTrack?: (event: AnalyticsEventName, payload: Record<string, unknown>) => void;
  }
}
function deviceType() {
  const width = window.innerWidth;
  if (width < 768) return 'mobile';
  if (width < 1024) return 'tablet';
  return 'desktop';
}
function referrerHost() {
  try { return document.referrer ? new URL(document.referrer).hostname : ''; }
  catch { return ''; }
}
function analyticsContext(tool?: ToolKey) {
  const route = routes.find((r) => r.key === (tool ?? routeFromPath())) ?? routes[0];
  return {
    page_path: route.path,
    page_slug: route.key,
    device_type: deviceType(),
    referrer_host: referrerHost(),
    data_version: dataVersion.dataVersion,
  };
}
function trackEvent(event: AnalyticsEventName, payload: Record<string, unknown> = {}) {
  const safePayload = { ...analyticsContext(), ...payload };
  window.palcalculatorEvents = window.palcalculatorEvents ?? [];
  window.palcalculatorEvents.push({ event, payload: safePayload, ts: new Date().toISOString() });
  window.palcalculatorTrack?.(event, safePayload);
}
function trackToolResult(tool: ToolKey, result: ResultState, extra: Record<string, unknown> = {}) {
  trackEvent(result.severity === 'ok' ? 'tool_success' : 'tool_error', {
    ...analyticsContext(tool),
    tool_type: tool,
    result_type: result.severity === 'ok' ? 'calculator_result' : 'calculator_error',
    error_code: result.severity === 'ok' ? undefined : (result.code ?? 'UNKNOWN_ERROR'),
    recoverable: result.severity !== 'ok',
    ...extra,
  });
}
const ownedPalStorageKey = 'palcalculator:owned-pals:v1';
function ownedCountBucket(count: number) { if (count <= 0) return '0'; if (count <= 5) return '1-5'; if (count <= 15) return '6-15'; if (count <= 30) return '16-30'; return '31+'; }
function readStoredOwnedPalIds() {
  try {
    const raw = window.localStorage.getItem(ownedPalStorageKey);
    if (!raw) return { ids: [] as string[], available: true };
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return { ids: [] as string[], available: true };
    const valid = parsed.filter((id): id is string => typeof id === 'string' && Boolean(pals.find((pal) => pal.id === id)));
    return { ids: [...new Set(valid)], available: true };
  }
  catch { return { ids: [] as string[], available: false }; }
}
function writeStoredOwnedPalIds(ids: string[]) {
  try { window.localStorage.setItem(ownedPalStorageKey, JSON.stringify(ids)); return true; }
  catch { return false; }
}
function displayNamesForOwnedIds(ids: string[]) { return ids.map((id) => pals.find((pal) => pal.id === id)?.displayName).filter((name): name is string => Boolean(name)); }
function palSlug(value: unknown) { return findPal(String(value ?? ''))?.slug; }
function passiveSlug(value: string) {
  const normalized = value.trim().toLowerCase();
  return passives.find((passive) => passive.id === normalized || passive.displayName.toLowerCase() === normalized)?.id;
}
function boundedNumber(value: unknown, fallback: number, min: number, max: number) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.min(max, Math.max(min, Math.round(parsed)));
}
function currentParams() { return new URLSearchParams(window.location.search); }
function queryValue(key: string, fallback: string) { return currentParams().get(key) ?? fallback; }
function queryNumber(key: string, fallback: number, min: number, max: number) { return boundedNumber(currentParams().get(key), fallback, min, max); }
function queryMode(fallback: 'pair' | 'target') { const mode = currentParams().get('mode'); return mode === 'pair' || mode === 'target' ? mode : fallback; }
function sharePayloadForTool(tool: ToolKey, payload: SharePayload) {
  if (tool === 'breeding' || tool === 'one0') {
    const mode = payload.mode === 'target' ? 'target' : 'pair';
    return mode === 'target' ? { mode, target: palSlug(payload.target) } : { mode, parentA: palSlug(payload.a ?? payload.parentA), parentB: palSlug(payload.b ?? payload.parentB) };
  }
  if (tool === 'route') return { target: palSlug(payload.target), maxGen: boundedNumber(payload.maxGen, 3, 1, 8) };
  if (tool === 'iv' || tool === 'stats') return { pal: palSlug(payload.pal), level: boundedNumber(payload.level, 50, 1, 60), hp: boundedNumber(payload.hp, 0, 0, 99999), attack: boundedNumber(payload.attack, 0, 0, 99999), defense: boundedNumber(payload.defense, 0, 0, 99999) };
  if (tool === 'passives') return { target: palSlug(payload.target), passives: String(payload.desired ?? '').split(',').map(passiveSlug).filter(Boolean).join(',') };
  return payload;
}
function shareUrl(tool: ToolKey, payload: SharePayload) {
  const route = routes.find((r) => r.key === tool) ?? routes[0];
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(sharePayloadForTool(tool, payload))) if (value !== undefined && String(value).trim()) params.set(key, String(value));
  const path = `${route.path}${params.toString() ? `?${params.toString()}` : ''}`;
  return `${window.location.origin}${path}`;
}
function hasQueryState(route: RouteMeta) {
  return ['breeding','route','iv','stats','passives','one0'].includes(route.key) && currentParams().toString().length > 0;
}

